void amc::ctypelen_CopyIn(amc::FCtypelen &row, dmmeta::Ctypelen &in) {
    row.ctype = in.ctype;
    row.len = in.len;
    row.alignment = in.alignment;
    row.padbytes = in.padbytes;
    row.plaindata = in.plaindata;
}

// --- amc.FCtypelen..Uninit
