// If out of memory, process is killed.
amc::FFflag& amc::fflag_Alloc() {
    amc::FFflag* row = fflag_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("amc.out_of_mem  field:amc.FDb.fflag  comment:'Alloc failed'");
    }
    return *row;
}

// --- amc.FDb.fflag.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
amc::FFflag* amc::fflag_AllocMaybe() {
    amc::FFflag *row = (amc::FFflag*)fflag_AllocMem();
    if (row) {
        new (row) amc::FFflag; // call constructor
    }
    return row;
}

// --- amc.FDb.fflag.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
amc::FFflag* amc::fflag_InsertMaybe(const dmmeta::Fflag &value) {
    amc::FFflag *row = &fflag_Alloc(); // if out of memory, process dies. if input error, return NULL.
    fflag_CopyIn(*row,const_cast<dmmeta::Fflag&>(value));
    bool ok = fflag_XrefMaybe(*row); // this may return false
    if (!ok) {
        fflag_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- amc.FDb.fflag.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* amc::fflag_AllocMem() {
    u64 new_nelems     = _db.fflag_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    amc::FFflag*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.fflag_lary[bsr];
        if (!lev) {
            lev=(amc::FFflag*)amc::lpool_AllocMem(sizeof(amc::FFflag) * (u64(1)<<bsr));
            _db.fflag_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.fflag_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- amc.FDb.fflag.RemoveAll
// Remove all elements from Lary
void amc::fflag_RemoveAll() {
    for (u64 n = _db.fflag_n; n>0; ) {
        n--;
        fflag_qFind(u64(n)).~FFflag(); // destroy last element
        _db.fflag_n = i64(n);
    }
}

// --- amc.FDb.fflag.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void amc::fflag_RemoveLast() {
    u64 n = _db.fflag_n;
    if (n > 0) {
        n -= 1;
        fflag_qFind(u64(n)).~FFflag();
        _db.fflag_n = i64(n);
    }
}

// --- amc.FDb.fflag.InputMaybe
static bool amc::fflag_InputMaybe(dmmeta::Fflag &elem) {
    bool retval = true;
    retval = fflag_InsertMaybe(elem) != nullptr;
    return retval;
}

// --- amc.FDb.fflag.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool amc::fflag_XrefMaybe(amc::FFflag &row) {
    bool retval = true;
    (void)row;
    // insert fflag into index ind_fflag
    if (true) { // user-defined insert condition
        bool success = ind_fflag_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "amc.duplicate_key  xref:amc.FDb.ind_fflag"; // check for duplicate key
            return false;
        }
    }
    amc::FField* p_field = amc::ind_field_Find(row.field);
    if (UNLIKELY(!p_field)) {
        algo_lib::ResetErrtext() << "amc.bad_xref  index:amc.FDb.ind_field" << Keyval("key", row.field);
        return false;
    }
    // insert fflag into index c_fflag
    if (true) { // user-defined insert condition
        bool success = c_fflag_InsertMaybe(*p_field, row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "amc.duplicate_key  xref:amc.FField.c_fflag"; // check for duplicate key
            return false;
        }
    }
    return retval;
}

// --- amc.FDb.ind_fflag.Find
// Find row by key. Return NULL if not found.
amc::FFflag* amc::ind_fflag_Find(const algo::strptr& key) {
    u32 index = algo::Smallstr150_Hash(0, key) & (_db.ind_fflag_buckets_n - 1);
    amc::FFflag *ret = _db.ind_fflag_buckets_elems[index];
    for (; ret && !((*ret).field == key); ret = ret->ind_fflag_next) {
    }
    return ret;
}

// --- amc.FDb.ind_fflag.FindX
// Look up row by key and return reference. Throw exception if not found
amc::FFflag& amc::ind_fflag_FindX(const algo::strptr& key) {
    amc::FFflag* ret = ind_fflag_Find(key);
    vrfy(ret, tempstr() << "amc.key_error  table:ind_fflag  key:'"<<key<<"'  comment:'key not found'");
    return *ret;
}

// --- amc.FDb.ind_fflag.GetOrCreate
// Find row by key. If not found, create and x-reference a new row with with this key.
amc::FFflag& amc::ind_fflag_GetOrCreate(const algo::strptr& key) {
    amc::FFflag* ret = ind_fflag_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &fflag_Alloc();
        (*ret).field = key;
        bool good = fflag_XrefMaybe(*ret);
        if (!good) {
            fflag_RemoveLast(); // delete offending row, any existing xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "amc.create_error  table:ind_fflag  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- amc.FDb.ind_fflag.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool amc::ind_fflag_InsertMaybe(amc::FFflag& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_fflag_next == (amc::FFflag*)-1)) {// check if in hash already
        row.ind_fflag_hashval = algo::Smallstr150_Hash(0, row.field);
        ind_fflag_Reserve(1);
        u32 index = row.ind_fflag_hashval & (_db.ind_fflag_buckets_n - 1);
        amc::FFflag* *prev = &_db.ind_fflag_buckets_elems[index];
        do {
            amc::FFflag* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).field == row.field) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_fflag_next;
        } while (true);
        if (retval) {
            row.ind_fflag_next = *prev;
            _db.ind_fflag_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- amc.FDb.ind_fflag.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void amc::ind_fflag_Remove(amc::FFflag& row) {
    if (LIKELY(row.ind_fflag_next != (amc::FFflag*)-1)) {// check if in hash already
        u32 index = row.ind_fflag_hashval & (_db.ind_fflag_buckets_n - 1);
        amc::FFflag* *prev = &_db.ind_fflag_buckets_elems[index]; // addr of pointer to current element
        while (amc::FFflag *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_fflag_next; // unlink (singly linked list)
                _db.ind_fflag_n--;
                row.ind_fflag_next = (amc::FFflag*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_fflag_next;
        }
    }
}

// --- amc.FDb.ind_fflag.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void amc::ind_fflag_Reserve(int n) {
    ind_fflag_AbsReserve(_db.ind_fflag_n + n);
}

// --- amc.FDb.ind_fflag.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void amc::ind_fflag_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_fflag_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(amc::FFflag*);
        u32 new_size = new_nbuckets * sizeof(amc::FFflag*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        amc::FFflag* *new_buckets = (amc::FFflag**)amc::lpool_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("amc.out_of_memory  field:amc.FDb.ind_fflag");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_fflag_buckets_n; i++) {
            amc::FFflag* elem = _db.ind_fflag_buckets_elems[i];
            while (elem) {
                amc::FFflag &row        = *elem;
                amc::FFflag* next       = row.ind_fflag_next;
                u32 index          = row.ind_fflag_hashval & (new_nbuckets-1);
                row.ind_fflag_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        amc::lpool_FreeMem(_db.ind_fflag_buckets_elems, old_size);
        _db.ind_fflag_buckets_elems = new_buckets;
        _db.ind_fflag_buckets_n = new_nbuckets;
    }
}

