// --- amc.FDb.falias.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool amc::falias_XrefMaybe(amc::FFalias &row) {
    bool retval = true;
    (void)row;
    amc::FField* p_srcfield = amc::ind_field_Find(row.srcfield);
    if (UNLIKELY(!p_srcfield)) {
        algo_lib::ResetErrtext() << "amc.bad_xref  index:amc.FDb.ind_field" << Keyval("key", row.srcfield);
        return false;
    }
    // falias: save pointer to srcfield
    if (true) { // user-defined insert condition
        row.p_srcfield = p_srcfield;
    }
    amc::FField* p_field = amc::ind_field_Find(row.field);
    if (UNLIKELY(!p_field)) {
        algo_lib::ResetErrtext() << "amc.bad_xref  index:amc.FDb.ind_field" << Keyval("key", row.field);
        return false;
    }
    // insert falias into index c_falias
    if (true) { // user-defined insert condition
        bool success = c_falias_InsertMaybe(*p_field, row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "amc.duplicate_key  xref:amc.FField.c_falias"; // check for duplicate key
            return false;
        }
    }
    return retval;
}

