// --- amc.FDb.ind_license.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void amc::ind_license_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_license_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(amc::FLicense*);
        u32 new_size = new_nbuckets * sizeof(amc::FLicense*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        amc::FLicense* *new_buckets = (amc::FLicense**)amc::lpool_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("amc.out_of_memory  field:amc.FDb.ind_license");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_license_buckets_n; i++) {
            amc::FLicense* elem = _db.ind_license_buckets_elems[i];
            while (elem) {
                amc::FLicense &row        = *elem;
                amc::FLicense* next       = row.ind_license_next;
                u32 index          = row.ind_license_hashval & (new_nbuckets-1);
                row.ind_license_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        amc::lpool_FreeMem(_db.ind_license_buckets_elems, old_size);
        _db.ind_license_buckets_elems = new_buckets;
        _db.ind_license_buckets_n = new_nbuckets;
    }
}

// --- amc.FDb.c_ssimfile_sorted.Insert
// Insert pointer to row into array. Row must not already be in array;
// no duplicate check is performed, so a duplicate insert silently appears twice.
void amc::c_ssimfile_sorted_Insert(amc::FSsimfile& row) {
    if (!row.c_ssimfile_sorted_in_ary) {
        c_ssimfile_sorted_Reserve(1);
        u64 n  = _db.c_ssimfile_sorted_n++;
        _db.c_ssimfile_sorted_elems[n] = &row;
        row.c_ssimfile_sorted_in_ary = true;
    }
}

// --- amc.FDb.c_ssimfile_sorted.InsertMaybe
// Insert pointer to row in array.
// If row is already in the array, do nothing.
// Return value: whether element was inserted into array.
bool amc::c_ssimfile_sorted_InsertMaybe(amc::FSsimfile& row) {
    bool retval = !c_ssimfile_sorted_InAryQ(row);
    c_ssimfile_sorted_Insert(row); // check is performed in _Insert again
    return retval;
}

// --- amc.FDb.c_ssimfile_sorted.Remove
// Find element using linear scan. If element is in array, remove, otherwise do nothing
void amc::c_ssimfile_sorted_Remove(amc::FSsimfile& row) {
    i64 n = _db.c_ssimfile_sorted_n;
    if (bool_Update(row.c_ssimfile_sorted_in_ary,false)) {
        amc::FSsimfile* *elems = _db.c_ssimfile_sorted_elems;
        // search backward, so that most recently added element is found first.
        // if found, shift array.
        for (i64 i = n-1; i>=0; i--) {
            amc::FSsimfile* elem = elems[i]; // fetch element
            if (elem == &row) {
                i64 j = i + 1;
                size_t nbytes = sizeof(amc::FSsimfile*) * (n - j);
                memmove(elems + i, elems + j, nbytes);
                _db.c_ssimfile_sorted_n = n - 1;
                break;
            }
        }
    }
}

// --- amc.FDb.c_ssimfile_sorted.Reserve
// Reserve space in index for N more elements;
void amc::c_ssimfile_sorted_Reserve(u64 n) {
    u64 old_max = _db.c_ssimfile_sorted_max;
    if (UNLIKELY(_db.c_ssimfile_sorted_n + n > old_max)) {
        u64 new_max  = u64_Max(u64_Max(old_max * 2, _db.c_ssimfile_sorted_n + n), 4);
        u64 old_size = old_max * sizeof(amc::FSsimfile*);
        u64 new_size = new_max * sizeof(amc::FSsimfile*);
        void *new_mem = amc::lpool_ReallocMem(_db.c_ssimfile_sorted_elems, old_size, new_size);
        if (UNLIKELY(!new_mem)) {
            FatalErrorExit("amc.out_of_memory  field:amc.FDb.c_ssimfile_sorted");
        }
        _db.c_ssimfile_sorted_elems = (amc::FSsimfile**)new_mem;
        _db.c_ssimfile_sorted_max = new_max;
    }
}

// --- amc.FDb.zd_ssimfile_todo.Insert
// Insert row into linked list. If row is already in linked list, do nothing.
void amc::zd_ssimfile_todo_Insert(amc::FSsimfile& row) {
    if (!zd_ssimfile_todo_InLlistQ(row)) {
        amc::FSsimfile* old_tail = _db.zd_ssimfile_todo_tail;
        row.zd_ssimfile_todo_next = NULL;
        row.zd_ssimfile_todo_prev = old_tail;
        _db.zd_ssimfile_todo_tail = &row;
        amc::FSsimfile **new_row_a = &old_tail->zd_ssimfile_todo_next;
        amc::FSsimfile **new_row_b = &_db.zd_ssimfile_todo_head;
        amc::FSsimfile **new_row = old_tail ? new_row_a : new_row_b;
        *new_row = &row;
        _db.zd_ssimfile_todo_n++;
    }
}

// --- amc.FDb.zd_ssimfile_todo.Remove
// Remove element from index. If element is not in index, do nothing.
void amc::zd_ssimfile_todo_Remove(amc::FSsimfile& row) {
    if (zd_ssimfile_todo_InLlistQ(row)) {
        amc::FSsimfile* old_head       = _db.zd_ssimfile_todo_head;
        (void)old_head; // in case it's not used
        amc::FSsimfile* prev = row.zd_ssimfile_todo_prev;
        amc::FSsimfile* next = row.zd_ssimfile_todo_next;
        // if element is first, adjust list head; otherwise, adjust previous element's next
        amc::FSsimfile **new_next_a = &prev->zd_ssimfile_todo_next;
        amc::FSsimfile **new_next_b = &_db.zd_ssimfile_todo_head;
        amc::FSsimfile **new_next = prev ? new_next_a : new_next_b;
        *new_next = next;
        // if element is last, adjust list tail; otherwise, adjust next element's prev
        amc::FSsimfile **new_prev_a = &next->zd_ssimfile_todo_prev;
        amc::FSsimfile **new_prev_b = &_db.zd_ssimfile_todo_tail;
        amc::FSsimfile **new_prev = next ? new_prev_a : new_prev_b;
        *new_prev = prev;
        _db.zd_ssimfile_todo_n--;
        row.zd_ssimfile_todo_next=(amc::FSsimfile*)-1; // not-in-list
    }
}

// --- amc.FDb.zd_ssimfile_todo.RemoveAll
// Empty the index. (The rows are not deleted)
void amc::zd_ssimfile_todo_RemoveAll() {
    amc::FSsimfile* row = _db.zd_ssimfile_todo_head;
    _db.zd_ssimfile_todo_head = NULL;
    _db.zd_ssimfile_todo_tail = NULL;
    _db.zd_ssimfile_todo_n = 0;
    while (row) {
        amc::FSsimfile* row_next = row->zd_ssimfile_todo_next;
        row->zd_ssimfile_todo_next  = (amc::FSsimfile*)-1;
        row->zd_ssimfile_todo_prev  = NULL;
        row = row_next;
    }
}

// --- amc.FDb.zd_ssimfile_todo.RemoveFirst
// If linked list is empty, return NULL. Otherwise unlink and return pointer to first element.
amc::FSsimfile* amc::zd_ssimfile_todo_RemoveFirst() {
    amc::FSsimfile *row = NULL;
    row = _db.zd_ssimfile_todo_head;
    if (row) {
        amc::FSsimfile *next = row->zd_ssimfile_todo_next;
        _db.zd_ssimfile_todo_head = next;
        amc::FSsimfile **new_end_a = &next->zd_ssimfile_todo_prev;
        amc::FSsimfile **new_end_b = &_db.zd_ssimfile_todo_tail;
        amc::FSsimfile **new_end = next ? new_end_a : new_end_b;
        *new_end = NULL;
        _db.zd_ssimfile_todo_n--;
        row->zd_ssimfile_todo_next = (amc::FSsimfile*)-1; // mark as not-in-list
    }
    return row;
}

// --- amc.FDb.zd_ssimfile_todo.InsertBefore
// Insert row before given element, or at tail when before is NULL; no-op if row is already in list.
void amc::zd_ssimfile_todo_InsertBefore(amc::FSsimfile& row, amc::FSsimfile* before) {
    if (!zd_ssimfile_todo_InLlistQ(row) && &row != before) {
        amc::FSsimfile* next = before;
        amc::FSsimfile* prev = next ? next->zd_ssimfile_todo_prev : _db.zd_ssimfile_todo_tail;
        row.zd_ssimfile_todo_next = next;
        row.zd_ssimfile_todo_prev = prev;
        amc::FSsimfile **prev_link_a = &prev->zd_ssimfile_todo_next;
        amc::FSsimfile **prev_link_b = &_db.zd_ssimfile_todo_head;
        *(prev ? prev_link_a : prev_link_b) = &row;
        amc::FSsimfile **next_link_a = &next->zd_ssimfile_todo_prev;
        amc::FSsimfile **next_link_b = &_db.zd_ssimfile_todo_tail;
        *(next ? next_link_a : next_link_b) = &row;
        _db.zd_ssimfile_todo_n++;
    }
}

// --- amc.FDb.cfast.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
amc::FCfast& amc::cfast_Alloc() {
    amc::FCfast* row = cfast_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("amc.out_of_mem  field:amc.FDb.cfast  comment:'Alloc failed'");
    }
    return *row;
}

// --- amc.FDb.cfast.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
amc::FCfast* amc::cfast_AllocMaybe() {
    amc::FCfast *row = (amc::FCfast*)cfast_AllocMem();
    if (row) {
        new (row) amc::FCfast; // call constructor
    }
    return row;
}

// --- amc.FDb.cfast.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
amc::FCfast* amc::cfast_InsertMaybe(const dmmeta::Cfast &value) {
    amc::FCfast *row = &cfast_Alloc(); // if out of memory, process dies. if input error, return NULL.
    cfast_CopyIn(*row,const_cast<dmmeta::Cfast&>(value));
    bool ok = cfast_XrefMaybe(*row); // this may return false
    if (!ok) {
        cfast_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- amc.FDb.cfast.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* amc::cfast_AllocMem() {
    u64 new_nelems     = _db.cfast_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    amc::FCfast*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.cfast_lary[bsr];
        if (!lev) {
            lev=(amc::FCfast*)amc::lpool_AllocMem(sizeof(amc::FCfast) * (u64(1)<<bsr));
            _db.cfast_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.cfast_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- amc.FDb.cfast.RemoveAll
// Remove all elements from Lary
void amc::cfast_RemoveAll() {
    for (u64 n = _db.cfast_n; n>0; ) {
        n--;
        cfast_qFind(u64(n)).~FCfast(); // destroy last element
        _db.cfast_n = i64(n);
    }
}

// --- amc.FDb.cfast.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void amc::cfast_RemoveLast() {
    u64 n = _db.cfast_n;
    if (n > 0) {
        n -= 1;
        cfast_qFind(u64(n)).~FCfast();
        _db.cfast_n = i64(n);
    }
}

// --- amc.FDb.cfast.InputMaybe
static bool amc::cfast_InputMaybe(dmmeta::Cfast &elem) {
    bool retval = true;
    retval = cfast_InsertMaybe(elem) != nullptr;
    return retval;
}

// --- amc.FDb.cfast.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool amc::cfast_XrefMaybe(amc::FCfast &row) {
    bool retval = true;
    (void)row;
    amc::FCtype* p_ctype = amc::ind_ctype_Find(row.ctype);
    if (UNLIKELY(!p_ctype)) {
        algo_lib::ResetErrtext() << "amc.bad_xref  index:amc.FDb.ind_ctype" << Keyval("key", row.ctype);
        return false;
    }
    // insert cfast into index c_cfast
    if (true) { // user-defined insert condition
        bool success = c_cfast_InsertMaybe(*p_ctype, row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "amc.duplicate_key  xref:amc.FCtype.c_cfast"; // check for duplicate key
            return false;
        }
    }
    return retval;
}

