// --- amc.FDb.ind_steptype.Find
// Find row by key. Return NULL if not found.
amc::FSteptype* amc::ind_steptype_Find(const algo::strptr& key) {
    u32 index = algo::Smallstr50_Hash(0, key) & (_db.ind_steptype_buckets_n - 1);
    amc::FSteptype *ret = _db.ind_steptype_buckets_elems[index];
    for (; ret && !((*ret).steptype == key); ret = ret->ind_steptype_next) {
    }
    return ret;
}

// --- amc.FDb.ind_steptype.FindX
// Look up row by key and return reference. Throw exception if not found
amc::FSteptype& amc::ind_steptype_FindX(const algo::strptr& key) {
    amc::FSteptype* ret = ind_steptype_Find(key);
    vrfy(ret, tempstr() << "amc.key_error  table:ind_steptype  key:'"<<key<<"'  comment:'key not found'");
    return *ret;
}

// --- amc.FDb.ind_steptype.GetOrCreate
// Find row by key. If not found, create and x-reference a new row with with this key.
amc::FSteptype& amc::ind_steptype_GetOrCreate(const algo::strptr& key) {
    amc::FSteptype* ret = ind_steptype_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &steptype_Alloc();
        (*ret).steptype = key;
        bool good = steptype_XrefMaybe(*ret);
        if (!good) {
            steptype_RemoveLast(); // delete offending row, any existing xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "amc.create_error  table:ind_steptype  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- amc.FDb.ind_steptype.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool amc::ind_steptype_InsertMaybe(amc::FSteptype& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_steptype_next == (amc::FSteptype*)-1)) {// check if in hash already
        row.ind_steptype_hashval = algo::Smallstr50_Hash(0, row.steptype);
        ind_steptype_Reserve(1);
        u32 index = row.ind_steptype_hashval & (_db.ind_steptype_buckets_n - 1);
        amc::FSteptype* *prev = &_db.ind_steptype_buckets_elems[index];
        do {
            amc::FSteptype* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).steptype == row.steptype) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_steptype_next;
        } while (true);
        if (retval) {
            row.ind_steptype_next = *prev;
            _db.ind_steptype_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- amc.FDb.ind_steptype.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void amc::ind_steptype_Remove(amc::FSteptype& row) {
    if (LIKELY(row.ind_steptype_next != (amc::FSteptype*)-1)) {// check if in hash already
        u32 index = row.ind_steptype_hashval & (_db.ind_steptype_buckets_n - 1);
        amc::FSteptype* *prev = &_db.ind_steptype_buckets_elems[index]; // addr of pointer to current element
        while (amc::FSteptype *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_steptype_next; // unlink (singly linked list)
                _db.ind_steptype_n--;
                row.ind_steptype_next = (amc::FSteptype*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_steptype_next;
        }
    }
}

// --- amc.FDb.ind_steptype.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void amc::ind_steptype_Reserve(int n) {
    ind_steptype_AbsReserve(_db.ind_steptype_n + n);
}

// --- amc.FDb.ind_steptype.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void amc::ind_steptype_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_steptype_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(amc::FSteptype*);
        u32 new_size = new_nbuckets * sizeof(amc::FSteptype*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        amc::FSteptype* *new_buckets = (amc::FSteptype**)amc::lpool_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("amc.out_of_memory  field:amc.FDb.ind_steptype");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_steptype_buckets_n; i++) {
            amc::FSteptype* elem = _db.ind_steptype_buckets_elems[i];
            while (elem) {
                amc::FSteptype &row        = *elem;
                amc::FSteptype* next       = row.ind_steptype_next;
                u32 index          = row.ind_steptype_hashval & (new_nbuckets-1);
                row.ind_steptype_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        amc::lpool_FreeMem(_db.ind_steptype_buckets_elems, old_size);
        _db.ind_steptype_buckets_elems = new_buckets;
        _db.ind_steptype_buckets_n = new_nbuckets;
    }
}

// --- amc.FDb.cjsbltin.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
amc::FCjsbltin& amc::cjsbltin_Alloc() {
    amc::FCjsbltin* row = cjsbltin_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("amc.out_of_mem  field:amc.FDb.cjsbltin  comment:'Alloc failed'");
    }
    return *row;
}

// --- amc.FDb.cjsbltin.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
amc::FCjsbltin* amc::cjsbltin_AllocMaybe() {
    amc::FCjsbltin *row = (amc::FCjsbltin*)cjsbltin_AllocMem();
    if (row) {
        new (row) amc::FCjsbltin; // call constructor
    }
    return row;
}

// --- amc.FDb.cjsbltin.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
amc::FCjsbltin* amc::cjsbltin_InsertMaybe(const dmmeta::Cjsbltin &value) {
    amc::FCjsbltin *row = &cjsbltin_Alloc(); // if out of memory, process dies. if input error, return NULL.
    cjsbltin_CopyIn(*row,const_cast<dmmeta::Cjsbltin&>(value));
    bool ok = cjsbltin_XrefMaybe(*row); // this may return false
    if (!ok) {
        cjsbltin_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- amc.FDb.cjsbltin.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* amc::cjsbltin_AllocMem() {
    u64 new_nelems     = _db.cjsbltin_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    amc::FCjsbltin*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.cjsbltin_lary[bsr];
        if (!lev) {
            lev=(amc::FCjsbltin*)amc::lpool_AllocMem(sizeof(amc::FCjsbltin) * (u64(1)<<bsr));
            _db.cjsbltin_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.cjsbltin_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- amc.FDb.cjsbltin.RemoveAll
// Remove all elements from Lary
void amc::cjsbltin_RemoveAll() {
    for (u64 n = _db.cjsbltin_n; n>0; ) {
        n--;
        cjsbltin_qFind(u64(n)).~FCjsbltin(); // destroy last element
        _db.cjsbltin_n = i64(n);
    }
}

// --- amc.FDb.cjsbltin.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void amc::cjsbltin_RemoveLast() {
    u64 n = _db.cjsbltin_n;
    if (n > 0) {
        n -= 1;
        cjsbltin_qFind(u64(n)).~FCjsbltin();
        _db.cjsbltin_n = i64(n);
    }
}

// --- amc.FDb.cjsbltin.InputMaybe
static bool amc::cjsbltin_InputMaybe(dmmeta::Cjsbltin &elem) {
    bool retval = true;
    retval = cjsbltin_InsertMaybe(elem) != nullptr;
    return retval;
}

// --- amc.FDb.cjsbltin.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool amc::cjsbltin_XrefMaybe(amc::FCjsbltin &row) {
    bool retval = true;
    (void)row;
    amc::FJsbltin* p_jsbltin = amc::ind_jsbltin_Find(row.jsbltin);
    if (UNLIKELY(!p_jsbltin)) {
        algo_lib::ResetErrtext() << "amc.bad_xref  index:amc.FDb.ind_jsbltin" << Keyval("key", row.jsbltin);
        return false;
    }
    // cjsbltin: save pointer to jsbltin
    if (true) { // user-defined insert condition
        row.p_jsbltin = p_jsbltin;
    }
    amc::FCtype* p_ctype = amc::ind_ctype_Find(row.ctype);
    if (UNLIKELY(!p_ctype)) {
        algo_lib::ResetErrtext() << "amc.bad_xref  index:amc.FDb.ind_ctype" << Keyval("key", row.ctype);
        return false;
    }
    // insert cjsbltin into index c_cjsbltin
    if (true) { // user-defined insert condition
        bool success = c_cjsbltin_InsertMaybe(*p_ctype, row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "amc.duplicate_key  xref:amc.FCtype.c_cjsbltin"; // check for duplicate key
            return false;
        }
    }
    return retval;
}

