// --- amc.FField.bh_bitfld_curs.Add
static void amc::field_bh_bitfld_curs_Add(field_bh_bitfld_curs &curs, amc::FBitfld& row) {
    u32 n = curs.temp_n;
    int i = n;
    curs.temp_n = n+1;
    amc::FBitfld* *elems = curs.temp_elems;
    while (i>0) {
        int j = (i-1)/2;
        amc::FBitfld* p = elems[j];
        if (!bh_bitfld_ElemLt((*curs.parent), row,*p)) {
            break;
        }
        elems[i]=p;
        i=j;
    }
    elems[i]=&row;
}

// --- amc.FField.bh_bitfld_curs.Reserve
void amc::field_bh_bitfld_curs_Reserve(field_bh_bitfld_curs &curs, int n) {
    if (n > curs.temp_max) {
        size_t old_size   = sizeof(void*) * curs.temp_max;
        size_t new_size   = sizeof(void*) * bh_bitfld_N((*curs.parent));
        curs.temp_elems   = (amc::FBitfld**)amc::lpool_ReallocMem(curs.temp_elems, old_size, new_size);
        if (!curs.temp_elems) {
            algo::FatalErrorExit("amc.cursor_out_of_memory  func:amc.FField.bh_bitfld_curs.Reserve");
        }
        curs.temp_max       = bh_bitfld_N((*curs.parent));
    }
}

// --- amc.FField.bh_bitfld_curs.Reset
// Reset cursor. If HEAP is non-empty, add its top element to CURS.
void amc::field_bh_bitfld_curs_Reset(field_bh_bitfld_curs &curs, amc::FField &parent) {
    curs.parent       = &parent;
    field_bh_bitfld_curs_Reserve(curs, bh_bitfld_N((*curs.parent)));
    curs.temp_n = 0;
    if (parent.bh_bitfld_n > 0) {
        amc::FBitfld &first = *parent.bh_bitfld_elems[0];
        curs.temp_elems[0] = &first; // insert first element in heap
        curs.temp_n = 1;
    }
}

// --- amc.FField.bh_bitfld_curs.Next
// Advance cursor.
void amc::field_bh_bitfld_curs_Next(field_bh_bitfld_curs &curs) {
    amc::FBitfld* *elems = curs.temp_elems;
    int n = curs.temp_n;
    if (n > 0) {
        // remove top element from heap
        amc::FBitfld* dead = elems[0];
        int i       = 0;
        amc::FBitfld* last = curs.temp_elems[n-1];
        // downheap last elem
        do {
            amc::FBitfld* choose = last;
            int l         = i*2+1;
            if (l<n) {
                amc::FBitfld* el = elems[l];
                int r     = l+1;
                r        -= r==n;
                amc::FBitfld* er = elems[r];
                if (bh_bitfld_ElemLt((*curs.parent),*er,*el)) {
                    el  = er;
                    l   = r;
                }
                bool b = bh_bitfld_ElemLt((*curs.parent),*el,*last);
                if (b) choose = el;
                if (!b) l = n;
            }
            elems[i] = choose;
            i = l;
        } while (i < n);
        curs.temp_n = n-1;
        int index = dead->field_bh_bitfld_idx;
        i = (index*2+1);
        if (i < bh_bitfld_N((*curs.parent))) {
            amc::FBitfld &elem = *curs.parent->bh_bitfld_elems[i];
            field_bh_bitfld_curs_Add(curs, elem);
        }
        if (i+1 < bh_bitfld_N((*curs.parent))) {
            amc::FBitfld &elem = *curs.parent->bh_bitfld_elems[i + 1];
            field_bh_bitfld_curs_Add(curs, elem);
        }
    }
}

// --- amc.FField..Uninit
void amc::FField_Uninit(amc::FField& parent) {
    ind_field_Remove(parent); // remove field from index ind_field
    amc::FCtype* p_ctype = amc::ind_ctype_Find(ctype_Get(parent));
    if (p_ctype)  {
        c_field_Remove(*p_ctype, parent);// remove field from index c_field
    }
    if (p_ctype)  {
        c_optfld_Remove(*p_ctype, parent);// remove field from index c_optfld
    }
    if (p_ctype)  {
        c_datafld_Remove(*p_ctype, parent);// remove field from index c_datafld
    }
    amc::FCtype* p_arg = amc::ind_ctype_Find(parent.arg);
    if (p_arg)  {
        zd_inst_Remove(*p_arg, parent);// remove field from index zd_inst
    }
    amc::FNs* p_ns = amc::ind_ns_Find(ns_Get(parent));
    if (p_ns)  {
        c_globfld_Remove(*p_ns, parent);// remove field from index c_globfld
    }
    if (p_arg)  {
        zd_access_Remove(*p_arg, parent);// remove field from index zd_access
    }
    zs_ordkeyfield_Remove(parent); // remove field from index zs_ordkeyfield
    if (p_ctype)  {
        zd_varlenfld_Remove(*p_ctype, parent);// remove field from index zd_varlenfld
    }

    // amc.FField.c_fcond.Uninit (Ptrary)  //fcond rows watching this field
    amc::lpool_FreeMem(parent.c_fcond_elems, sizeof(amc::FFcond*)*parent.c_fcond_max); // (amc.FField.c_fcond)

    // amc.FField.c_pmaskfld_member.Uninit (Ptrary)  //
    amc::lpool_FreeMem(parent.c_pmaskfld_member_elems, sizeof(amc::FPmaskfldMember*)*parent.c_pmaskfld_member_max); // (amc.FField.c_pmaskfld_member)

    // amc.FField.c_ffast.Uninit (Ptrary)  //
    amc::lpool_FreeMem(parent.c_ffast_elems, sizeof(amc::FFfast*)*parent.c_ffast_max); // (amc.FField.c_ffast)

    // amc.FField.bh_bitfld.Uninit (Bheap)  //
    amc::lpool_FreeMem((u8*)parent.bh_bitfld_elems, sizeof(amc::FBitfld*)*parent.bh_bitfld_max); // (amc.FField.bh_bitfld)

    // amc.FField.c_fconst.Uninit (Ptrary)  //
    amc::lpool_FreeMem(parent.c_fconst_elems, sizeof(amc::FFconst*)*parent.c_fconst_max); // (amc.FField.c_fconst)

    // amc.FField.c_ffunc.Uninit (Ptrary)  //
    amc::lpool_FreeMem(parent.c_ffunc_elems, sizeof(amc::FFunc*)*parent.c_ffunc_max); // (amc.FField.c_ffunc)
}

