void amc::FXref_Init(amc::FXref& parent) {
    parent.inscond = algo::CppExpr("true");
    parent.p_field = NULL;
    parent.p_ctype = NULL;
    parent.c_nocascdel = NULL;
    parent.p_viafld = NULL;
    parent.p_keyfld = NULL;
    parent.ctype_zs_xref_next = (amc::FXref*)-1; // (amc.FCtype.zs_xref) not-in-list
    parent.ind_xref_next = (amc::FXref*)-1; // (amc.FDb.ind_xref) not-in-hash
    parent.ind_xref_hashval = 0; // stored hash value
    parent.field_zd_xref_keyfld_next = (amc::FXref*)-1; // (amc.FField.zd_xref_keyfld) not-in-list
    parent.field_zd_xref_keyfld_prev = NULL; // (amc.FField.zd_xref_keyfld)
}

// --- amc.FXref..Uninit
void amc::FXref_Uninit(amc::FXref& parent) {
    ind_xref_Remove(parent); // remove xref from index ind_xref
    amc::FField* p_field = amc::ind_field_Find(parent.field);
    if (p_field)  {
        c_xref_Remove(*p_field, parent);// remove xref from index c_xref
    }
    amc::FField* p_keyfld = amc::ind_field_Find(keyfld_Get(parent));
    if (p_keyfld)  {
        zd_xref_keyfld_Remove(*p_keyfld, parent);// remove xref from index zd_xref_keyfld
    }
}

// --- amc.FieldId.value.ToCstr
// Convert numeric value of field to one of predefined string constants.
// If string is found, return a static C string. Otherwise, return NULL.
const char* amc::value_ToCstr(const amc::FieldId& parent) {
    const char *ret = NULL;
    switch(value_GetEnum(parent)) {
        case amc_FieldId_value             : ret = "value";  break;
        case amc_FieldId_len               : ret = "len";  break;
        case amc_FieldId_str               : ret = "str";  break;
    }
    return ret;
}

// --- amc.FieldId.value.Print
// Convert value to a string. First, attempt conversion to a known string.
// If no string matches, print value as a numeric value.
void amc::value_Print(const amc::FieldId& parent, algo::cstring &lhs) {
    const char *strval = value_ToCstr(parent);
    if (strval) {
        lhs << strval;
    } else {
        lhs << parent.value;
    }
}

// --- amc.FieldId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool amc::value_SetStrptrMaybe(amc::FieldId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 3: {
            switch (u64(algo::ReadLE16(rhs.elems))|(u64(rhs[2])<<16)) {
                case LE_STR3('l','e','n'): {
                    value_SetEnum(parent,amc_FieldId_len); ret = true; break;
                }
                case LE_STR3('s','t','r'): {
                    value_SetEnum(parent,amc_FieldId_str); ret = true; break;
                }
            }
            break;
        }
        case 5: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(rhs[4])<<32)) {
                case LE_STR5('v','a','l','u','e'): {
                    value_SetEnum(parent,amc_FieldId_value); ret = true; break;
                }
            }
            break;
        }
    }
    return ret;
}

// --- amc.FieldId.value.SetStrptr
// Convert string to field.
// If the string is invalid, set numeric value to DFLT
void amc::value_SetStrptr(amc::FieldId& parent, algo::strptr rhs, amc_FieldIdEnum dflt) {
    if (!value_SetStrptrMaybe(parent,rhs)) value_SetEnum(parent,dflt);
}

// --- amc.FieldId.value.ReadStrptrMaybe
// Convert string to field. Return success value
bool amc::value_ReadStrptrMaybe(amc::FieldId& parent, algo::strptr rhs) {
    bool retval = false;
    retval = value_SetStrptrMaybe(parent,rhs); // try symbol conversion
    if (!retval) { // didn't work? try reading as underlying type
        retval = i32_ReadStrptrMaybe(parent.value,rhs);
    }
    return retval;
}

// --- amc.FieldId..ReadStrptrMaybe
// Read fields of amc::FieldId from an ascii string.
// The format of the string is the format of the amc::FieldId's only field
bool amc::FieldId_ReadStrptrMaybe(amc::FieldId &parent, algo::strptr in_str) {
    bool retval = true;
    retval = retval && value_ReadStrptrMaybe(parent, in_str);
    return retval;
}

// --- amc.FieldId..Print
// print string representation of ROW to string STR
// cfmt:amc.FieldId.String  printfmt:Raw
void amc::FieldId_Print(amc::FieldId row, algo::cstring& str) {
    amc::value_Print(row, str);
}

